inline std::variant<double, lucent::String> Convert<std::variant<double, lucent::String>>::fromJs(jsi::Runtime& rt, const jsi::Value& v, const Path& p) {
  if (v.isNumber()) {
    return std::variant<double, lucent::String>(Convert<double>::fromJs(rt, v, p));
  }
  if (v.isString()) {
    return std::variant<double, lucent::String>(Convert<lucent::String>::fromJs(rt, v, p));
  }
  throwBoundaryError(rt, p, "a number or a string", v);
}

inline jsi::Value Convert<std::variant<double, lucent::String>>::toJs(jsi::Runtime& rt, Host& h, const std::variant<double, lucent::String>& v) {
  return std::visit([&](const auto& x) -> jsi::Value {
    return Convert<std::decay_t<decltype(x)>>::toJs(rt, h, x);
  }, v);
}

